// The G-code's "generated by" line names DolphinSlicer, which printer hosts show as the slicer
// (Moonraker reads "; generated by <name> <version> on <date> at <time>"). The version stays the
// slicing core's. Only that line changes: 3MF files keep OrcaSlicer's application name, which
// desktop checks when it opens a project.
// SPDX-License-Identifier: AGPL-3.0-or-later

const FROM = /(^|\n)(; generated by )OrcaSlicer (?=\S+ on )/;
/** The line is in the header, within the first lines. */
const SEARCH = 4096;

/** The G-code with DolphinSlicer in its "generated by" line, as Blob parts (no copy of the rest). */
export function brandGcode(gcode: ArrayBuffer): BlobPart[] {
  const head = new TextDecoder('latin1').decode(new Uint8Array(gcode, 0, Math.min(SEARCH, gcode.byteLength)));
  const m = FROM.exec(head);
  if (!m) return [gcode];
  const at = m.index + m[1]!.length;
  return [new Uint8Array(gcode, 0, at), `${m[2]}DolphinSlicer `, new Uint8Array(gcode, m.index + m[0].length)];
}
